contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: the hash to lock as guess, the amount to send when locking (must be 1 ether to succeed),
    // and a flag whether to attempt settle after locking.
    function run(bytes32 guessHash, uint256 lockAmount, bool doSettle) public payable {
        require(lockAmount == 1 ether);
        require(address(this).balance >= lockAmount);

        // initial observations
        uint256 beforeBalanceC = address(c).balance;

        // try to lock in a guess; record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: lockAmount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // observe state after lock attempt
        uint256 afterLockBalanceC = address(c).balance;

        // optionally attempt to call settle and observe whether it reverted and balances
        bool settleReverted = false;
        uint256 afterSettleBalanceC = afterLockBalanceC;
        if (doSettle) {
            try c.settle() {
                settleReverted = false;
                afterSettleBalanceC = address(c).balance;
            } catch {
                settleReverted = true;
                afterSettleBalanceC = address(c).balance;
            }
        }

        // The invariant to prove for all inputs:
        // 1) If lockInGuess reverted then c's balance did not increase.
        // 2) If lockInGuess succeeded then c.balance increased by exactly 1 ether.
        // 3) If settle was called and did not revert, then c.balance either decreased by exactly 2 ether
        //    (meaning the test contract received 2 ether payout) or did not decrease at all (no payout).
        // Express as a general assert combining these observations.
        bool condition1 = lockReverted ? (afterLockBalanceC == beforeBalanceC) : (afterLockBalanceC == beforeBalanceC + 1 ether);

        bool settleCondition;
        if (!doSettle) {
            // if we didn't call settle, no further constraint beyond condition1
            settleCondition = true;
        } else {
            if (settleReverted) {
                // if settle reverted, c's balance must be unchanged from after lock
                settleCondition = (afterSettleBalanceC == afterLockBalanceC);
            } else {
                // if settle succeeded, either c paid out 2 ether (balance decreased by 2) or paid nothing
                settleCondition = (afterSettleBalanceC + 2 ether == afterLockBalanceC) || (afterSettleBalanceC == afterLockBalanceC);
            }
        }

        assert(condition1 && settleCondition);
    }

    receive() external payable {}
}

