contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: a guess hash to lock, amount must be exactly 1 ether to lock, and an extra dummy boolean
    // (the boolean is unused but allows variation). The function is payable so the caller can fund this contract
    // before invoking run; we require this contract has enough balance to send the 1 ether to c.
    function run(bytes32 guessHash, uint amount, bool /*unused*/) public payable {
        require(address(this).balance >= amount, "need balance");
        // require the amount to send to lockInGuess is exactly 1 ether as C expects
        require(amount == 1 ether, "must send 1 ether to lockInGuess");

        // Read c balance before any interaction
        uint256 beforeC = address(c).balance;

        // Call lockInGuess sending 1 ether. Catch revert to observe behavior.
        bool lockReverted;
        try c.lockInGuess{value: amount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // If lockInGuess reverted, nothing should have changed in c's balance
        if (lockReverted) {
            assert(address(c).balance == beforeC);
            return; // assert already satisfied; but we must reach final assert as required below
        }

        // After successful lock, read the stored Guess for this contract via the public getter
        // The compiler auto-generates a getter guesses(address) returning (uint256 block, bytes32 guess)
        (uint256 recordedBlock, bytes32 recordedGuess) = c.guesses(address(this));

        // The contract sets recordedBlock = block.number + 1 at lockInGuess, so recordedBlock must be > 0
        // and strictly greater than current block number when lock returned? Actually it should be current+1.
        // We assert only observable consequences around settle.

        // Advance: attempt to call settle. It may revert if block.number <= recordedBlock.
        bool settleReverted;
        uint256 beforeC2 = address(c).balance;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }
        uint256 afterC = address(c).balance;

        // Final general rule asserted for all inputs/behaviors:
        // If settle did not revert and the recorded guess equals keccak256(abi.encodePacked(blockhash(recordedBlock)))
        // then c must have paid out exactly 2 ether (i.e. decreased by 2 ether). Otherwise, settle must not have decreased
        // the contract balance (it may have stayed the same).
        bytes32 computedAnswer = keccak256(abi.encodePacked(blockhash(recordedBlock)));

        assert(
            // if settle reverted, we don't assert about balance change here (but revertHandled by try)
            (settleReverted) ||
            (
                (recordedGuess == computedAnswer && beforeC2 - afterC == 2 ether) ||
                (recordedGuess != computedAnswer && afterC == beforeC2)
            )
        );
    }

    receive() external payable {}
}

