        require(address(this).balance >= amount);

        // observe C's balance and the guess info before any interaction
        uint256 beforeC = address(c).balance;
        // The auto-generated getter for mapping guesses returns (uint, bytes32)
        (uint256 beforeBlock, bytes32 beforeGuess) = c.guesses(address(this));

        // attempt lockInGuess with provided amount (may revert)
        bool lockReverted;
        try c.lockInGuess{value: amount}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // observe after-call state
