    function run(bytes32 hash, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance for test");
        // Pre-read c balance and this contract balance
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // call lockInGuess with value 'amount'
        try c.lockInGuess{value: amount}(hash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable: after-call c balance
        uint afterC = address(c).balance;

        // The contract C requires exactly 1 ether to lockInGuess, and requires guesses[msg.sender].block == 0.
        // If our call did not revert, then amount must have been 1 ether and c's balance increased by 1 ether.
