        // Instead, we use the fact that settle will only proceed when block.number > stored block; thus the stored block must be nonzero and at least 1 greater than current block when set.
        // We can observe this by calling settle in a try/catch and seeing it revert because block.number is not greater than the stored block.

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
