    // We take a guess hash and amounts for lockInGuess (must supply funds) and nothing for settle.
    // The test will: fund and call lockInGuess(hash) with amount lockAmt, then call settle()
    // We observe reverts and balances and assert a general invariant relating successful payout to a prior successful lockInGuess with 1 ether.
    function run(bytes32 hash, uint lockAmt) public payable {
        require(address(this).balance >= lockAmt, "insufficient balance for lockAmt");
        // Record contract C balance before any interaction
        uint c_before = address(c).balance;

        bool lockReverted;
        // attempt lockInGuess with provided amount
        try c.lockInGuess{value: lockAmt}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Record balances after lock attempt but before settle
        uint c_after_lock = address(c).balance;
        uint this_after_lock = address(this).balance;

        bool settleReverted;
        // attempt settle which may transfer 2 ether to this contract
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Record balances after settle attempt
        uint c_after_settle = address(c).balance;
        uint this_after_settle = address(this).balance;

        // The intended general rule:
        // If settle did not revert and this test contract received 2 ether from C (i.e. this_after_settle == this_after_lock + 2 ether),
        // then the earlier lockInGuess must have succeeded (lockReverted == false) and that call had been made with exactly 1 ether,
        // and as a consequence C's balance after settle equals its balance before the lock call (c_after_settle == c_before).
        // We express "lock was called with exactly 1 ether" by observable balance change: if lock succeeded then c_after_lock == c_before + 1 ether.

        bool receivedTwo = (this_after_settle == this_after_lock + 2 ether);
        bool lockSucceededAndOne = (!lockReverted && (c_after_lock == c_before + 1 ether));
        bool c_balance_restored = (c_after_settle == c_before);

        assert(!receivedTwo || (lockSucceededAndOne && c_balance_restored));
    }

    // Allow contract to receive Ether from C during settle payout
    receive() external payable {}
}

